  "remote.account.deleteKept": "Nous ne gardons que ce qui empêche un second essai gratuit (empreintes de votre adresse, de votre indicatif et de l'ordinateur de votre station, et les dates de votre essai) et les données de facturation exigées par la loi.",
  "remote.account.deleteSubscription": "Supprimer votre compte résilie votre abonnement immédiatement : l'accès prend fin maintenant et la partie non utilisée de la période n'est pas remboursée. Si votre premier paiement date de moins de 14 jours, demandez le remboursement avant de supprimer.",
  "remote.account.deleteConfirm": "Saisissez {{word}} pour confirmer",
  "remote.account.deleteButton": "Supprimer mon compte",
  "remote.account.cancelFailed": "Votre abonnement n'a pas pu être résilié, rien n'a donc été supprimé. Réessayez dans quelques minutes.",
  "remote.stationLimitReached": "Ce compte a déjà deux stations. Révoquez-en une que vous n'utilisez pas avant d'en appairer une autre.",
  "remote.pairingExpired": "Ce code d'appairage a expiré ou a déjà été utilisé. Obtenez-en un nouveau depuis Nexus au shack.",
  "remote.pairingCodeMalformed": "Un code d'appairage comporte seize caractères, uniquement les chiffres 0-9 et les lettres a-f. Vérifiez s'il y a un O à la place d'un zéro.",
  "remote.deviceLimitReached": "Cette station a déjà autant de navigateurs approuvés qu'elle en autorise. Oubliez-en un que vous n'utilisez plus, puis réessayez.",
  "remote.signInAgain": "Votre connexion a expiré. Reconnectez-vous pour continuer.",
  "remote.signInRefused": "La connexion a été refusée. Si vous venez de créer un compte, confirmez votre adresse e-mail avec le code ou le lien que nous vous avons envoyé, puis reconnectez-vous.",
  "remote.confirmEmailTitle": "Confirmez votre adresse e-mail pour terminer",
  "remote.confirmEmailBody": "Votre inscription a fonctionné, mais l'adresse e-mail n'est pas encore confirmée. Saisissez sur l'écran d'inscription le code à six chiffres que nous vous avons envoyé par e-mail ou, si vous avez reçu un lien, cliquez dessus. Revenez ensuite ici pour continuer. Si vous revenez sur cette page, l'adresse n'est pas encore confirmée.",
  "remote.confirmEmailSpam": "Rien reçu après quelques minutes ? Cherchez un e-mail de Nexus Remote dans vos spams ou courriers indésirables. Un code reste valable quinze minutes, un lien cinq jours.",
  "remote.confirmEmailContinue": "J'ai confirmé mon adresse e-mail — continuer",
  "remote.useDifferentAccount": "Utiliser un autre compte",
  "remote.trialActiveElsewhere": "Cette adresse e-mail a déjà un essai Remote en cours avec une autre méthode de connexion, par exemple Google au lieu d'un mot de passe. Déconnectez-vous, puis connectez-vous comme la première fois.",
  "remote.tryLater": "Trop de tentatives. Attendez jusqu'à dix minutes, puis réessayez.",
  "remote.stationOffline": "Cette station est injoignable. Vérifiez que Nexus tourne au shack, que Remote y est activé (Paramètres → À distance) et que l'ordinateur est réveillé et en ligne.",
  "remote.sessionEnded": "L’accès distant à cette station a pris fin, ce navigateur a donc été déconnecté. Vérifiez ci-dessous votre essai et vos stations.",
  "remote.sessionEndedBeta": "L’accès distant à cette station a pris fin, ce navigateur a donc été déconnecté. Vérifiez ci-dessous vos stations.",
  "remote.browserPerStation": "Chaque station autorise ses navigateurs séparément : ce navigateur doit donc aussi être autorisé pour cette station.",
  "remote.sharedComputerHint": "Se déconnecter laisse ce navigateur autorisé. Sur un ordinateur partagé, appuyez sur « Retirer l’autorisation de ce navigateur » pour chaque station avant de vous déconnecter.",
  "remote.disconnect": "Déconnecter et revenir aux stations",
