  "remote.thisStationKey": "Clé de cette station : {{key}}",
  "remote.stationKey.changed": "La clé de cette station a changé : le service Remote indique maintenant une autre clé que celle que ce navigateur a conservée. Rien ne se connecte tant que vous n’avez pas accepté la nouvelle clé. Comparez-la avec « Clé de cette station » dans Nexus à la station, et acceptez-la seulement si elles correspondent.",
  "remote.stationKey.kept": "Clé conservée par ce navigateur : {{key}}",
