  "remote.revokeHint": "La révocation déconnecte cette station et retire l’autorisation de tous les navigateurs qui l’utilisaient. Pour la réutiliser, associez-la de nouveau au shack et autorisez-y de nouveau vos navigateurs.",
  "remote.revokeStation": "Révoquer l’accès à la station",
