  "remote.nativeStationKeyPinned": "Le service Remote détient pour cette station une autre clé que celle qui signe son direct : les navigateurs refusent donc son direct. Utilisez Révoquer l’accès à la station, puis associez à nouveau cette station.",
  "remote.vaultFailed": "Déverrouillez le coffre d’identifiants du système et réessayez. L’accès reste désactivé si l’identifiant ne peut pas être enregistré en sécurité.",
  "remote.nativeRevoked": "L'accès de cette station a été révoqué depuis un navigateur, elle ne se connecte donc plus. Rien n'est cassé ici — réappairez-la ci-dessous quand vous la voudrez de nouveau.",
  "remote.nativeTrialEnded": "Votre essai Remote est terminé, cette station n’a donc pas pu être ajoutée au compte. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeTrialDisabled": "L’accès Remote de ce compte a été désactivé, cette station n’a donc pas pu être ajoutée. Ce n’est pas la même chose qu’un essai arrivé à terme. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeCallsignInvalid": "L’essai Remote est d’un par indicatif : renseignez d’abord l’indicatif de votre station dans Réglages → Station, puis associez de nouveau cette station. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeCallsignNotLicensed": "L’indicatif de Réglages → Station n’est pas une licence américaine active dans la liste des licences de la FCC, cette station n’a donc pas pu être ajoutée. Vérifiez qu’il n’y a pas de faute de frappe. Une nouvelle licence y apparaît après un jour environ. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeTrialUsedByCallsign": "Cet indicatif a déjà eu un essai Remote sous un autre compte, cette station n’a donc pas pu être ajoutée. Si c’est votre indicatif, écrivez au support depuis l’adresse e-mail de votre licence. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeTrialUsedOnThisPc": "Cet ordinateur a déjà eu un essai Remote sous un autre compte, cette station n’a donc pas pu être ajoutée. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeUpdateRequired": "Ajouter une station à Remote demande un Nexus plus récent. Mettez Nexus à jour, puis associez de nouveau cette station. Votre radio, votre journal et vos réglages sont intacts.",
  "remote.nativeTrialActiveElsewhere": "Cette adresse e-mail a déjà un essai Remote en cours avec une autre méthode de connexion, par exemple Google au lieu d’un mot de passe, cette station n’a donc pas pu être ajoutée. Dans votre navigateur, déconnectez-vous, connectez-vous comme la première fois, puis associez de nouveau cette station. Votre radio, votre journal et vos réglages sont intacts.",
