  "remote.approval.bodyAgain": "Ce navigateur était déjà autorisé, mais il ne peut pas lancer le direct tant que vous ne l’autorisez pas à nouveau ici. En direct, il peut utiliser cette station comme vous le feriez ici, émission comprise. Autorisez-le seulement si cette clé correspond à celle qu’affiche le navigateur : {{key}}.",
