  "remote.approval.computerBodyAgain": "Nexus sous {{platform}} était déjà autorisé, mais il ne peut pas se connecter tant que vous ne l’autorisez pas à nouveau ici. Connecté, il peut utiliser cette station comme vous le feriez ici, émission comprise. Autorisez-le seulement si cette clé correspond à celle qu’affiche Nexus sur cet ordinateur : {{key}}.",
