  "remote.approval.heldComputerBody": "Nexus sous {{platform}} s’est connecté à votre compte Remote. Il peut déjà écouter et régler, et l’émission attend que vous l’autorisiez. Autorisez-le seulement si cette clé correspond à celle qu’affiche Nexus sur cet ordinateur : {{key}}.",
