  "lanWindow.internet.heldCodePaired": "Vérifiez cette clé avant que la voie internet ne transporte quoi que ce soit. À la station, dans Accès à distance, « Clé de cette station » doit afficher les mêmes groupes. Tant que vous n’avez pas confirmé qu’elle correspond, « Piloter depuis cet ordinateur » n’utilise pas la voie internet. Utiliser « Piloter depuis cet ordinateur » sur le réseau de la station la vérifie aussi : si la station y montre cette même clé, la voie internet s’active d’elle-même.",
