  "aprs.head.hint": "Paquet AFSK-1200 — décoder positions et messages, envoyer une balise",
  "aprs.head.packets": "{{count}} paq.",
  "aprs.health.advice.clipping": "La salve ÉCRÊTE (crête {{peak}}, {{samples}} échantillon(s) en butée) — baissez le niveau de sortie USB AF de la radio, ou le niveau d'entrée Windows de ce périphérique. Le paquet supporte bien l'écrêtage, cela coûte donc de la marge plutôt que des décodages, mais il n'y a aucune raison de taper en butée.",
  "aprs.health.advice.quiet": "La salve a crêté à {{peak}}, bien en dessous de la plage saine {{min}} à {{max}} — montez le niveau de sortie USB AF de la radio (IC-9700 : SET > Connectors > USB AF Output Level) ou le niveau d'entrée Windows de ce périphérique. Cela donne de la marge face au bruit ; ce n'est pas en soi la cause d'un échec de somme de contrôle.",
  "aprs.health.dbfs.silence": "silence",
  "aprs.health.decoding.detail": "{{count}} paquets décodés depuis l'armement. En direct {{level}}.",
  "aprs.health.decoding.detail.aged": "{{count}} paquets décodés depuis l'armement, le dernier il y a {{age}}. En direct {{level}}.",
  "aprs.health.decoding.label": "{{count}} décodés",
  "aprs.health.level.peak": "crête d'entrée sur les dernières 0.1 s : {{db}} dBFS",
  "aprs.health.level.silence": "entrée sur les dernières 0.1 s : silence numérique (exactement zéro)",
  "aprs.health.listening.detail": "L'audio arrive au décodeur et aucun paquet n'a été entendu récemment — canal calme. En direct {{level}}. Squelch ouvert, le souffle doit se situer vers {{hiss}} ; une salve de paquet doit crêter entre {{min}} et {{max}}.",
  "aprs.health.listening.label": "À l'écoute",
  "aprs.health.noCapture.detail": "Armé, mais aucun échantillon audio n'arrive — le périphérique de capture ne délivre rien. Vérifiez que le périphérique d'entrée (RX) dans Réglages ▸ Radio ▸ Audio est bien la radio (pas un microphone ni un périphérique débranché) ; ce que vous entendez dans le haut-parleur ne dit rien de ce que l'application capture.",
  "aprs.health.noCapture.label": "Pas d'entrée",
  "aprs.health.norf.detail": "Cette radio ne couvre pas {{freq}} MHz, elle ne peut donc pas recevoir l'APRS en RF. L'APRS en RF demande une radio VHF. Le flux internet fonctionne sans — activez-le pour voir le trafic APRS rapporté par d'autres stations.",
  "aprs.health.norf.label": "Pas de radio 2 m",
  "aprs.health.off.detail": "Le décodeur APRS ne tourne pas. Armez l'écoute pour décoder l'audio RX.",
  "aprs.health.off.label": "Écoute arrêtée",
  "aprs.health.silent.detail": "L'entrée est vivante et délivre de l'audio, mais c'est du silence — normalement cela veut juste dire que le squelch est fermé entre les paquets, ce à quoi ressemble un canal FM au repos. Pour confirmer le routage, ouvrez le squelch : le souffle doit apparaître ici sous forme de niveau. Si cela reste silencieux squelch ouvert, le mauvais périphérique d'entrée est sélectionné. En direct {{level}}.",
  "aprs.health.silent.label": "Silence",
  "aprs.health.unreadable.detail": "{{count}} salves entendues depuis l'armement, la dernière il y a {{age}} — aucune n'a passé la somme de contrôle. Une partie est normale : quand le squelch s'ouvre au milieu d'une salve, le début du paquet est perdu, et un paquet entendu à moitié ne passera jamais. Ce n'est un défaut que si rien ne décode jamais — auquel cas vérifiez que la radio est sur {{channel}} en FM.{{advice}} Dernière salve à {{burst}} ; en direct {{level}}.",
  "aprs.health.unreadable.label": "{{count}} CRC ratés",
  "aprs.health.wrongFreq.detail": "La radio est sur {{dial}} — l'APRS demande {{want}}. Rien sur ce canal ne peut décoder en paquet APRS, quel que soit le niveau audio. Réglez sur le canal APRS pour commencer à l'entendre.",
  "aprs.health.wrongFreq.label": "Mauvaise fréquence",
  "aprs.health.wrongFreqMode.detail": "La radio est sur {{dial}} {{mode}} — l'APRS demande {{want}} FM. Rien sur ce canal ne peut décoder en paquet APRS, quel que soit le niveau audio. Réglez sur le canal APRS pour commencer à l'entendre.",
  "aprs.health.wrongMode.detail": "La radio est sur {{want}} mais en {{mode}} — l'APRS demande la FM. De l'audio paquet FM démodulé en SSB est brouillé : rien ne décodera, même avec un signal fort. Réglez sur le canal APRS pour commencer à l'entendre.",
  "aprs.health.wrongMode.label": "Mauvais mode",
  "aprs.inet.chip.title": "{{detail}} Cliquez pour les réglages du flux internet.",
