  "aprs.monitor.title.auto": "Armé automatiquement à l'ouverture d'APRS : RÉCEPTION SEULE. Il n'enverra jamais d'acquittement automatique. Pour les autoriser, arrêtez-le et armez-le vous-même, puis activez le TX. Cliquez pour arrêter.",
