  "aprs.radioNote.detail": "{{count}} de vos radios couvrent cette bande, APRS a donc dû choisir. Il suit la radio active, actuellement {{name}} — si ce n'est pas celle où votre audio paquet est câblé, c'est pour cela que rien ne décode. Les règles de routage décident quelle radio prend une bande : Réglages → Radios.",
