  "assist.keep": "Vos propres réglages ne sont jamais réécrits. Terminer le mode UNASSISTED rétablit le décodeur et les flux exactement comme vous les aviez.",
  "assist.sources.off": "Sources d'assistance désactivées : décodeur CW, DX cluster / RBN, manquants PSK Reporter, Super Check Partial, historique des indicatifs.",
  "assist.sources.offSince": "Sources d'assistance désactivées depuis {{since}} : décodeur CW, DX cluster / RBN, manquants PSK Reporter, Super Check Partial, historique des indicatifs.",
  "assist.sources.on": "Le décodeur CW, le DX cluster / RBN, les manquants PSK Reporter, Super Check Partial et l'historique des indicatifs fournissent une aide pour les indicatifs et les échanges.",
  "assist.sources.onSince": "Le décodeur CW, le DX cluster / RBN, les manquants PSK Reporter, Super Check Partial et l'historique des indicatifs fournissent une aide pour les indicatifs et les échanges depuis {{since}}.",
  "assist.state.assisted": "ASSISTED",
  "assist.state.unassisted": "UNASSISTED",
  "assist.toggle.declare": "Déclarer une participation UNASSISTED",
  "assist.toggle.end": "Terminer la participation UNASSISTED",
  "assist.why.arrl": "Les concours <b>ARRL</b> appellent cela l'aide au spotting et citent “PSKReporter, Telnet, DX spotting websites or bulletin board systems, automated multi-channel decoders”. La catégorie Single Operator ne peut pas l'utiliser (HCAT.1.1 : “Use of spotting assistance is not permitted.”). <b>Single Operator Unlimited</b> le peut (HCAT.2.1). Le glossaire de l’ARRL définit un décodeur multi-canal comme un logiciel qui “displays multiple decoded signals at the same time”. Nexus décode un signal à la fois : cette définition ne décrit donc pas son décodeur CW. Elle décrit en revanche les flux cluster, RBN et PSK Reporter.",
  "assist.why.checkRules": "Les règlements varient d'un concours à l'autre et changent d'une année sur l'autre : <b>vérifiez le règlement du concours auquel vous participez</b>. Cette note rapporte ce que publient actuellement CQ WW et l'ARRL. Ce n'est pas un classement de catégorie.",
  "assist.why.cqww": "La règle VIII.2 de <b>CQ WW</b> compte “a CW decoder, DX cluster, DX spotting Web sites … local or remote call sign and frequency decoding technology (e.g., CW Skimmer or Reverse Beacon Network)” comme une aide à la recherche de QSO. En utiliser une place la participation en <b>Single Operator Assisted</b> (V.A.2) au lieu de Single Operator (V.A.1).",
  "assist.why.notCovered": "<b>Ce que cet interrupteur ne couvre pas :</b> les spots d'activateurs POTA et SOTA continuent d'arriver. Aucun des deux règlements ne cite ces flux, mais tous deux définissent l'assistance assez largement pour les inclure : désactivez donc les fonctions POTA/SOTA à la main si le concours auquel vous participez les compte.",
  "assist.why.ownDecodes": "Les <b>décodages numériques de votre propre radio</b>, FT8 et FT4 compris, continuent d'alimenter le tableau Manquants en mode UNASSISTED. Aucun des deux règlements ne les met à part : tous deux comptent comme assistance toute technologie qui identifie un indicatif ou un multiplicateur, donc n'utilisez pas le tableau Manquants pour trouver des stations si votre concours les compte. Vos envois sortants vers PSK Reporter continuent aussi, car l’ARRL précise que “Generating spotting information for use by other stations is not considered to be spotting assistance.”",
  "assist.why.summary": "Ce que cela implique pour votre catégorie de concours",
