  "fieldDay.club.import.title": "Verse le journal de concours d'un portable dans le log du club, comme sa synchronisation l'aurait fait : pour un hôte tombé en panne ou un portable qui n'a jamais synchronisé. Le journal s'appelle fieldday_backup_ suivi de 8 caractères et .adi, dans le dossier de réglages Nexus de ce portable. Importer le même fichier une seconde fois n'ajoute rien, et rien n'est retiré du log du club.",
