  "fieldDay.club.refused.chip": "Pas de synchro",
  "fieldDay.club.refused.serial": "La synchro club ne prend pas en charge {{contest}} : ses numéros de série doivent former une seule suite pour toute la participation, et chaque position donnerait les siens. Cette station n'héberge ni ne rejoint aucun événement de club, et chaque position tient son propre log.",
  "fieldDay.club.refused.transmitter": "La synchro club ne prend pas en charge {{contest}} : son log doit indiquer quel émetteur a fait chaque contact, et la synchro club ne numérote pas les émetteurs. Cette station n'héberge ni ne rejoint aucun événement de club, et chaque position tient son propre log.",
  "fieldDay.club.refused.unknown": "La synchro club ne prend pas en charge {{contest}} : les règles de concours que ce Nexus a chargées ne le contiennent pas. Vérifie les mises à jour des règles dans l'onglet Concours des réglages (les nouvelles règles s'appliquent au prochain démarrage de Nexus), ou choisis un autre concours. Cette station n'héberge ni ne rejoint aucun événement de club, et chaque position tient son propre log.",
  "fieldDay.club.refusedPosition": "{{name}} ({{call}}) refusée. Elle a reçu : « {{reason}} »",
  "fieldDay.club.refusedCall": "{{call}} refusée. Elle a reçu : « {{reason}} »",
  "fieldDay.club.give.label": "Donner à ce portable sa position",
  "fieldDay.club.give.title": "Retire cette position du club au portable qui la tient et la donne à celui-ci. L'autre portable est déconnecté et refusé, et les contacts qu'il a envoyés comme cette position quittent le log du club jusqu'à ce qu'il le rejoigne ; celui-ci envoie au club chaque contact de son log. La ligne de l'autre portable porte alors ce même bouton, si bien qu'un clic erroné s'annule de la même façon.",
  "fieldDay.club.give.given": "{{name}} reçoit sa position à sa prochaine tentative, dans les 15 secondes, et envoie au club chaque contact de son log. Le portable qui la tenait est refusé, et sa ligne ici peut lui rendre la position.",
  "fieldDay.club.give.refused.stale": "Rien n'a changé : ce portable n'est plus sur cette liste. Il a rejoint, a cessé d'essayer, ou l'événement du club a redémarré.",
  "fieldDay.club.give.refused.notHosting": "Rien n'a changé : ce Nexus n'héberge aucun événement de club.",
  "fieldDay.club.give.refused.remote": "Seulement sur l'hôte : un clic via Remote ne donne aucune position.",
