  "fieldDay.club.link.why.noAnswer": "Aucune réponse : vérifiez que les deux portables sont sur le même réseau, que Nexus sur l'hôte a « Héberger un événement de club » activé et, si l'hôte tourne sous Windows, que son pare-feu laisse entrer Nexus : cliquez sur « Autoriser Nexus dans le Pare-feu Windows » dans Réglages ▸ Concours de l'hôte.",
