  "fieldDay.club.otherLocation": "{{name}} envoie {{sent}}, et ce club envoie {{club}}. Ses contacts sont enregistrés tels qu'il les a envoyés ; règle ce portable sur {{club}} pour que les suivants correspondent.",
  "fieldDay.club.boardFull": "Ce club a {{positions}} positions, autant que le tableau de club de chaque position peut en contenir. Au-delà, le tableau de chaque position laisse de côté les positions entendues il y a le plus longtemps ; les contacts, les alertes de doublon et le score restent synchronisés.",
  "fieldDay.club.boardCut": "Le tableau de club de chaque position montre {{shown}} des {{positions}} positions de ce club, autant qu'une ligne de club en porte, en laissant de côté celles entendues il y a le plus longtemps. Les contacts, les alertes de doublon et le score restent synchronisés.",
  "fieldDay.keptOut.running": { "one": "{{count}} contact du journal de concours de cet ordinateur a été journalisé lors d'une autre édition de {{contest}}, une répétition avant, par exemple, et n'est donc pas dans ce log.", "other": "{{count}} contacts du journal de concours de cet ordinateur ont été journalisés lors d'une autre édition de {{contest}}, une répétition avant, par exemple, et ne sont donc pas dans ce log." },
  "fieldDay.keptOut.contest": { "one": "{{count}} contact du journal de concours de cet ordinateur appartient à un autre concours et n'est donc pas dans ce log.", "other": "{{count}} contacts du journal de concours de cet ordinateur appartiennent à un autre concours et ne sont donc pas dans ce log." },
  "fieldDay.keptOut.kept": "Rien n'a été supprimé : ils restent dans le journal, tels qu'ils ont été journalisés.",
  "fieldDay.unsaved.since": "Les contacts ne sont pas enregistrés sur le disque. Ceux journalisés depuis {{time}} UTC sont seulement en mémoire, et une coupure de courant les perdrait. Exportez un fichier Cabrillo maintenant.",
  "fieldDay.unsaved.session": "Les contacts ne sont pas enregistrés sur le disque. Ceux journalisés pendant cette session sont seulement en mémoire, et une coupure de courant les perdrait. Exportez un fichier Cabrillo maintenant.",
  "fieldDay.unmerged.day": { "one": "{{count}} contact de {{contest}}, journalisé le {{date}} (UTC), n'est pas dans votre carnet. Le journal de concours de cet ordinateur le garde jusqu'à ce qu'il y soit.", "other": "{{count}} contacts de {{contest}}, journalisés le {{date}} (UTC), ne sont pas dans votre carnet. Le journal de concours de cet ordinateur les garde jusqu'à ce qu'ils y soient." },
  "fieldDay.unmerged.days": "{{count}} contacts de {{contest}}, journalisés du {{first}} au {{last}} (UTC), ne sont pas dans votre carnet. Le journal de concours de cet ordinateur les garde jusqu'à ce qu'ils y soient.",
  "fieldDay.unmerged.merge": { "one": "Le fusionner dans mon carnet", "other": "Fusionner ces {{count}} dans mon carnet" },
  "fieldDay.unmerged.title": "Ajoute ces contacts à votre carnet général tels qu'ils ont été journalisés. Vous pouvez appuyer deux fois sans risque : un contact déjà présent est ignoré, jamais dupliqué. Rien n'est mis en file d'envoi.",
  "fieldDay.club.board.empty": "Aucune position entendue pour l'instant — chaque autre position Nexus de ce réseau apparaît ici dès qu'elle journalise.",
