  "fieldDay.club.board.column.link": "État",
  "fieldDay.club.board.link.title": "Le lien de chaque position tel que cet hôte le voit. Connectée : entendue dans les {{window}} dernières secondes (une position envoie un signe de vie toutes les {{beat}} s). Reconnexion : plus entendue depuis plus de {{window}} s. Perdue : plus entendue depuis plus de {{dead}} s, quand l'hôte ferme son lien. Retirée : refusée jusqu'à ce que vous cliquiez sur Réadmettre.",
