  "fieldDay.club.grid.notHeard": "Plus entendue depuis plus de {{secs}} s",
  "fieldDay.club.remove.label": "Retirer",
  "fieldDay.club.remove.title": "Déconnecte cette position et la refuse quand elle réessaie, jusqu'à ce que vous cliquiez sur Réadmettre. Les contacts qu'elle a déjà envoyés restent dans le log du club, dans son score et dans les fichiers du club.",
  "fieldDay.club.remove.confirm.aria": "Retirer cette position ?",
  "fieldDay.club.remove.confirm.head": "Retirer {{name}} de l'événement du club ?",
  "fieldDay.club.remove.confirm.body": "Elle est déconnectée maintenant et refusée quand elle réessaie, jusqu'à ce que vous cliquiez sur Réadmettre sur sa ligne ici. Les contacts qu'elle a déjà envoyés restent dans le log du club, dans son score et dans les fichiers du club. Les contacts qu'elle note entre-temps restent dans son propre log et entrent quand vous la réadmettez.",
  "fieldDay.club.remove.confirm.yes": "La retirer",
