  "fieldDay.club.remove.done": "{{name}} est retirée : son lien est fermé, et elle est refusée jusqu'à ce que vous cliquiez sur Réadmettre. Ses contacts restent dans le log du club.",
  "fieldDay.club.allowBack.label": "Réadmettre",
  "fieldDay.club.allowBack.title": "Laisse cette position rejoindre de nouveau : elle rejoint d'elle-même à son prochain essai et envoie les contacts notés pendant son absence.",
