  "gettingStarted.radio.shot.usbBlurb": "La plupart des radios — un câble",
  "gettingStarted.radio.shot.usbLabel": "USB / Série",
  "gettingStarted.radio.testCat": "<b>Appuyez ensuite sur Tester CAT.</b> Nexus enregistre ce que vous avez saisi, démarre <code>rigctld</code> pour la radio et indique la fréquence VFO relue — ou l’erreur précise. Les autres programmes partagent la radio via l’adresse indiquée dans Réglages ▸ Radio ▸ <em>Limites d’émission et partage</em>.",
  "gettingStarted.radio.where": "Dans l’assistant, ou dans <b>Réglages ▸ Radio ▸ Radio et CAT</b>, cliquez sur <b>Détecter ma radio</b>.",
