  "gettingStarted.rail.station.blurb": "Qui vous êtes et où",
  "gettingStarted.rail.station.label": "Indicatif et locator",
  "gettingStarted.shot.label": "Dans Nexus",
  "gettingStarted.station.aria": "Étape 1 sur 4 : indicatif et locator",
  "gettingStarted.station.callout.body": "Quatre caractères vous placent au milieu d’un carré de ~100 miles de côté, et toutes les distances et tous les azimuts que vous lirez sont mesurés depuis ce point. <code>{{full}}</code> vaut mieux que <code>{{short}}</code>. Un locator mal formé est refusé d’emblée — l’assistant ne vous laisse pas passer.",
  "gettingStarted.station.callout.label": "Donnez les six caractères",
  "gettingStarted.station.callsign": "<b>Indicatif</b> — stocké en majuscules. Nexus ne démarre ni PSK Reporter ni le flux RBN/cluster tant qu’un indicatif valide n’est pas saisi : 3 à 10 caractères, au moins une lettre et un chiffre.",
  "gettingStarted.station.eyebrow": "Étape 1 sur 4 · Votre station",
  "gettingStarted.station.grid": "<b>Locator</b> — votre locator Maidenhead. QRZ affiche le vôtre.",
  "gettingStarted.station.heading": "Qui est à l’antenne ?",
  "gettingStarted.station.lede": "Votre indicatif et votre locator. Tout ce qui dépend de la position dans Nexus — la carte de propagation, les passages satellite, les distances, les azimuts, les fenêtres DXpédition, la localité des ouvertures VHF — est calculé à partir de ces deux champs.",
  "gettingStarted.station.name": "<b>Nom</b> — facultatif, dans Réglages ▸ Station. Alimente la macro CW <code>{NAME}</code> et le remplissage auto du journal.",
  "gettingStarted.station.shot.callsignLabel": "Indicatif",
  "gettingStarted.station.shot.caption": "Assistant de configuration ▸ étape 1 · relançable à tout moment depuis Réglages ▸ Apparence ▸ Fonctionnalités",
  "gettingStarted.station.shot.gridHint": "Locator Maidenhead (qrz.com affiche le vôtre). Donnez les 6 — 4 caractères vous placent au milieu d’un carré de ~100 miles de côté.",
  "gettingStarted.station.shot.gridLabel": "Locator",
  "gettingStarted.station.shot.next": "Suivant →",
  "gettingStarted.station.shot.skip": "Je le ferai moi-même",
  "gettingStarted.station.shot.sub": "Votre locator est la référence de tout ce qui dépend de la position — passages satellite, propagation, carte et fenêtres DXpédition en sont tous calculés.",
  "gettingStarted.station.shot.title": "Qui est à l’antenne ?",
  "gettingStarted.station.where": "Ouvrez l’assistant de premier lancement (il apparaît au premier démarrage) ou <b>Réglages ▸ Station</b> à tout moment.",
  "gettingStarted.title": "Prise en main",
  "gettingStarted.wizard.finish": "Terminer",
  "gettingStarted.wizard.log": "Votre journal",
  "gettingStarted.wizard.rig": "Votre radio",
  "gettingStarted.wizard.station": "Votre station",
  "gettingStarted.wsjtx.body": "Vos réflexes se transposent — sémantique du double-clic, <code>Esc</code> / <code>F4</code> / <code>F6</code> / <code>Alt+1–6</code>, Activité bande ancrée en bas, décodages précoces à 11.8\u00a0s, split Fake It, déplacement auto Hound. Vos réglages aussi : pointez l’étape 2 sur la même radio et les mêmes périphériques audio que WSJT-X, et donnez à l’étape 4 votre <code>wsjtx_log.adi</code>. JTAlert et GridTracker continuent de fonctionner dès que vous activez <b>WSJT-X UDP API</b> (désactivée par défaut) dans Réglages ▸ Journal et connecteurs ▸ <a>Intégrations et flux</a>. Son adresse est déjà celle que WSJT-X utilise par défaut : il n’y a donc rien d’autre à régler, et ils voient Nexus comme un WSJT-X.",
  "gettingStarted.wsjtx.label": "Vous venez de WSJT-X ? La voie courte",
  "gettingStarted.wsjtx.mac": "Sur un Mac, maintenez Fn pour les touches F — ou activez « Utiliser les touches F1, F2, etc. comme touches de fonction standard » dans Réglages Système ▸ Clavier, comme avec WSJT-X.",
