  "logbook.tools.bulk.previewFailed": "L’aperçu n’a pas pu être fait",
  "logbook.tools.bulk.uploads": "Une modification groupée ne change jamais l’indicatif contacté. Rien n’est envoyé d’ici. Un STATION_CALLSIGN remplacé par un autre indicatif est l’indicatif sous lequel un contact est envoyé : ses marques d’envoi sont effacées, le prochain envoi le renvoie sous le nouvel indicatif, et ses confirmations LoTW, eQSL et QRZ, appariées sous l’ancien indicatif, sont effacées ; les cartes QSL papier restent. Remplir un STATION_CALLSIGN vide, l’effacer, ou ajouter ou retirer /P n’efface aucune marque d’envoi ni confirmation. Mais un contact sans STATION_CALLSIGN est envoyé sous l’indicatif des Réglages : le remplir ou l’effacer peut donc changer l’indicatif sous lequel un contact part vers un service qui ne l’a pas encore reçu ; la confirmation les indique. Tout autre champ garde ses marques d’envoi et ses confirmations.",
  "logbook.tools.bulk.resend": { "one": "{{count}} d’entre eux a été envoyé sous un autre indicatif de station : il sera renvoyé sous le nouveau.", "other": "{{count}} d’entre eux ont été envoyés sous un autre indicatif de station : ils seront renvoyés sous le nouveau." },
  "logbook.tools.bulk.unconfirm": { "one": "{{count}} confirmation LoTW, eQSL ou QRZ a été appariée sous l’ancien indicatif de station et sera effacée. Les cartes QSL papier restent.", "other": "{{count}} confirmations LoTW, eQSL ou QRZ ont été appariées sous l’ancien indicatif de station et seront effacées. Les cartes QSL papier restent." },
