  "logbook.tools.grids.intro": "Les contacts enregistrés sans locator dont Nexus connaît le locator de la station : celui qu’elle a émis elle-même et que Nexus a entendu dans les 24 heures autour du contact (ALL.TXT, ou cette session), sinon son QTH de domicile d’après une recherche dans l’annuaire déjà faite (un indicatif sans barre et sans parc seulement, des 12 derniers mois). Seuls les contacts cochés sont complétés. Un locator entendu compte comme tout locator enregistré. Un locator de l’annuaire ne sert qu’à la distance et à la carte : il ne compte pour aucun diplôme de locators, ne remplit aucun besoin GRID et n’est envoyé à aucun service de journal. Un contact déjà envoyé garde ses marques d’envoi, comme pour toute modification ici : rien n’est renvoyé, et chaque service garde ce qu’il a reçu.",
