  "logbook.import.report.legend": "dans le fichier = enregistré (réécrit à l’identique) + normalisé (réécrit dans la graphie du log) + gardé tel quel (non modélisé, réécrit octet pour octet) + écarté (non réécrit, raison donnée)",
  "logbook.import.report.col.stored": "enregistré",
