  "logbook.lotw.upload.title": "Signer et envoyer vers LoTW vos QSO non encore envoyés, via TQSL (définissez votre Station Location dans les Réglages)",
  "logbook.markLotw.aria": "Marquer comme déjà sur LoTW",
  "logbook.markLotw.body": { "one": "À utiliser si vous avez importé un journal déjà envoyé vers LoTW par un autre moyen (Ham2K Polo, TQSL…). Cela marque le {{formatted}} QSO non envoyé comme déjà sur LoTW, pour que le compteur <b>Envoyer vers LoTW</b> cesse de proposer de le renvoyer. Seul le suivi propre à Nexus est modifié — rien n'est transmis, votre compte et votre log LoTW ne sont pas touchés. Les nouveaux QSO que vous ferez ensuite partiront normalement.", "other": "À utiliser si vous avez importé un journal déjà envoyé vers LoTW par un autre moyen (Ham2K Polo, TQSL…). Cela marque les {{formatted}} QSO non envoyés comme déjà sur LoTW, pour que le compteur <b>Envoyer vers LoTW</b> cesse de proposer de les renvoyer. Seul le suivi propre à Nexus est modifié — rien n'est transmis, votre compte et votre log LoTW ne sont pas touchés. Les nouveaux QSO que vous ferez ensuite partiront normalement." },
  "logbook.markLotw.cancel": "Annuler",
