  "logbook.parkStates.button": "Vérifier les États des parcs",
  "logbook.parkStates.buttonTitle": "Lister les contacts de parcs et de sommets dont l’État n’est pas celui de leur parc, et corriger ceux que vous cochez",
  "logbook.parkStates.title": "Vérifier les États des parcs",
  "logbook.parkStates.intro": "Ces contacts de parcs et de sommets portent un autre État que celui où se trouve leur parc ou sommet, ou aucun : Nexus enregistrait auparavant l’État de résidence de l’activateur, d’après sa licence ou sa fiche callbook. Cochez ceux à modifier. Rien ne change avant que vous appuyiez sur le bouton, et rien n’est renvoyé. Un contact confirmé commence décoché.",
  "logbook.parkStates.reading": "Lecture de votre journal…",
