  "logbook.parkStates.failed": "Impossible de vérifier les États des parcs",
  "logbook.confirmations.button": "Vérifier les confirmations",
  "logbook.confirmations.buttonTitle": "Télécharger tout votre historique LoTW, eQSL et QRZ, pour chaque service configuré, et lister les contacts dont la confirmation ou la marque d’envoi LoTW est attribuée par le service à un autre contact, ou à aucun, pour que vous cochiez celles à retirer",
  "logbook.confirmations.title": "Vérifier les confirmations",
  "logbook.confirmations.intro": "Les versions précédentes de Nexus pouvaient placer la confirmation d’un contact, de LoTW, eQSL ou QRZ, ou la marque indiquant que LoTW détient son envoi, sur un autre contact avec la même station, la même bande et le même mode le même jour UTC. « Vérifier » télécharge une fois tout votre historique auprès de chacun de ces services que vous avez configurés, ce qui peut prendre plusieurs minutes pour LoTW, et liste chaque contact portant une confirmation ou une marque d’envoi que les propres enregistrements du service attribuent à un autre contact, ou à aucun. Une ligne commence cochée seulement quand ces enregistrements le décident. Rien ne change avant que vous appuyiez sur le bouton, rien n’est envoyé et aucune carte QSL papier n’est touchée.",
  "logbook.confirmations.check": "Vérifier",
  "logbook.confirmations.checking": "Téléchargement de tout votre historique {{service}}…",
  "logbook.confirmations.notChecked": "Non vérifié : {{reason}}",
  "logbook.confirmations.none": "Les enregistrements de LoTW appuient chaque confirmation et marque d’envoi LoTW que cette vérification peut juger.",
  "logbook.confirmations.noneService": "Les enregistrements de {{service}} appuient chaque confirmation {{service}} que cette vérification peut juger.",
  "logbook.confirmations.change": "{{service}} ✓ → —",
  "logbook.confirmations.changeUpload": "LoTW : enregistré → non envoyé",
  "logbook.confirmations.why.moved": "La confirmation {{service}} est celle de votre contact de {{time}}",
  "logbook.confirmations.why.contradicted": "{{service}} détient ce contact non confirmé",
  "logbook.confirmations.why.orphan": "{{service}} confirme un QSO de {{time}} absent de votre journal",
  "logbook.confirmations.why.uploadMoved": "L’envoi que détient LoTW est celui de votre contact de {{time}}",
  "logbook.confirmations.why.uploadOrphan": "LoTW détient un envoi de {{time}} absent de votre journal",
  "logbook.confirmations.why.dateOnly": "pas d’heure",
  "logbook.confirmations.unticked.dateOnly": "Ce contact, ou un contact auquel la vérification le compare, a une date mais pas d’heure, donc les enregistrements de {{service}} ne peuvent pas dire à quel contact cela appartient. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.notReplayed": "Les versions précédentes n’ont pas pu placer cette confirmation ici en prenant le mauvais contact, elle est donc venue autrement : une importation, un ancien indicatif, ou une carte papier qu’un ancien Nexus a classée comme LoTW. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.notReplayedEqsl": "Les versions précédentes n’ont pas pu placer cette carte ici en prenant le mauvais contact, elle est donc venue autrement : une importation, un ancien indicatif, ou une confirmation qu’un ancien Nexus a classée comme eQSL. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.notReplayedQrz": "Les versions précédentes n’ont pas pu placer cette confirmation ici en prenant le mauvais contact, elle est donc venue autrement, par exemple d’une importation ou d’un ancien indicatif. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.uploadNotReplayed": "Les versions précédentes n’ont pas pu marquer ce contact en prenant le mauvais, la marque est donc venue autrement, par exemple d’une importation. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.tie": "L’enregistrement de {{service}} est exactement aussi proche de votre autre contact que de celui-ci, donc la vérification ne peut pas dire à qui il appartient. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.orphan": "Aucun contact de votre journal n’est à moins de 30 minutes de l’enregistrement de {{service}} : le QSO manque peut-être à votre journal, ou l’heure de ce contact est décalée de plus de 30 minutes. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.insideWindow": "L’enregistrement de {{service}} est aussi à moins de 30 minutes de ce contact, il peut donc être le sien. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.insideWindowEqsl": "La carte eQSL est aussi à moins de 30 minutes de ce contact, et une carte porte l’heure que l’autre station a enregistrée, elle peut donc être la sienne. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.unticked.notToTheMinute": "L’enregistrement non confirmé de {{service}} est proche de ce contact mais pas à sa minute, il peut donc appartenir à un autre QSO. Ne le cochez que si vous en êtes sûr.",
  "logbook.confirmations.badge.card": "carte papier — garde le crédit de diplôme",
  "logbook.confirmations.badge.credit": "crédit {{codes}} retiré",
  "logbook.confirmations.badge.submitted": "crédit demandé {{codes}} retiré",
  "logbook.confirmations.badge.owed": "jamais envoyé — part dans votre prochain envoi LoTW",
  "logbook.confirmations.badge.owedTitle": "LoTW ne détient aucun envoi de ce contact. Une fois modifié, « Envoyer vers LoTW » l’envoie, tout comme l’envoi automatique LoTW si vous l’avez activé.",
  "logbook.confirmations.gains": { "one": "{{count}} contact reçoit la confirmation que {{service}} détient pour lui.", "other": "{{count}} contacts reçoivent la confirmation que {{service}} détient pour eux." },
