  "logbook.confirmations.outOfScope": { "one": "{{count}} contact avec une confirmation {{service}} a été enregistré sous un autre indicatif que celui des Réglages ; cette vérification le laisse tel quel.", "other": "{{count}} contacts avec une confirmation {{service}} ont été enregistrés sous un autre indicatif que celui des Réglages ; cette vérification les laisse tels quels." },
  "logbook.confirmations.uploadsUnreached": { "one": "{{count}} contact marqué comme envoyé n’a aucun envoi que LoTW liste à moins d’un jour de lui ; cette vérification le laisse tel quel.", "other": "{{count}} contacts marqués comme envoyés n’ont aucun envoi que LoTW liste à moins d’un jour d’eux ; cette vérification les laisse tels quels." },
  "logbook.confirmations.uploadsOutOfScope": { "one": "{{count}} contact marqué comme envoyé a été enregistré sous un autre indicatif que celui des Réglages ; cette vérification le laisse tel quel.", "other": "{{count}} contacts marqués comme envoyés ont été enregistrés sous un autre indicatif que celui des Réglages ; cette vérification les laisse tels quels." },
