  "logbook.purge.label": "Vider le journal",
  "logbook.purge.syncWarn": "Cela réinitialise aussi votre <b>position de synchro LoTW et eQSL</b> : la prochaine synchro retélécharge tout votre historique de confirmations au lieu des seules correspondances récentes. C'est ce qui ramène vos confirmations après un vidage — mais c'est bien plus long qu'une synchro de routine, laissez-lui le temps de finir.",
  "logbook.purge.title": "Supprimer tous les contacts du journal local",
  "logbook.purge.typeWord": "Tapez <b>{{word}}</b> pour confirmer",
  "logbook.purge.warn": { "one": "Cela supprime <b>le {{count}} contact</b> de votre journal local et réécrit le fichier ADIF à vide. Cela ne retire <b>pas</b> ce que vous avez déjà envoyé vers LoTW, QRZ, eQSL ou ClubLog. Vous pouvez annuler tout le vidage depuis le message qui suit, ou plus tard avec <b>Annuler ce vidage</b> dans Supprimés récemment, tant que les Réglages conservent les contacts supprimés (90 jours, sauf si vous l'avez changé) ; les contacts peuvent aussi y être rétablis un par un. Pendant que la radio émet, un grand vidage n'est annulé qu'une fois l'émission arrêtée. Exportez d'abord une sauvegarde ADIF si vous pensez en avoir besoin plus tard.", "other": "Cela supprime <b>les {{count}} contacts</b> de votre journal local et réécrit le fichier ADIF à vide. Cela ne retire <b>pas</b> ce que vous avez déjà envoyé vers LoTW, QRZ, eQSL ou ClubLog. Vous pouvez annuler tout le vidage depuis le message qui suit, ou plus tard avec <b>Annuler ce vidage</b> dans Supprimés récemment, tant que les Réglages conservent les contacts supprimés (90 jours, sauf si vous l'avez changé) ; les contacts peuvent aussi y être rétablis un par un. Pendant que la radio émet, un grand vidage n'est annulé qu'une fois l'émission arrêtée. Exportez d'abord une sauvegarde ADIF si vous pensez en avoir besoin plus tard." },
