  "phone.rxMeter.label": "Niveau audio RX",
  "phone.scope.audio.label": "Bande passante",
  "phone.scope.audio.sub": "audio RX",
  "phone.scope.audio.title": "Spectre AUDIO du récepteur sur l'axe de votre radio : la ligne centrale est votre VFO, et la bande passante se place du côté de votre bande latérale (USB au-dessus, LSB en dessous) — l'autre moitié est vide parce qu'un récepteur SSB n'entend qu'un seul côté. Ce n'est pas un panadapter RF pleine bande : une voix remplit donc la bande passante au lieu de la traverser quand vous accordez.",
  "phone.scope.nativeRf.label": "Panadapter RF",
