  "sat.lane.blocked.detail": "Celestrak a refusé les récupérations directes d'éléments (HTTP 403/404) — les tentatives directes sont arrêtées pour 24 h. Le miroir hamradiotools.io continue d'essayer ; les éléments peuvent vieillir en attendant.",
  "sat.lane.blocked.message": "Sat : Celestrak bloqué",
  "sat.lane.mostlyStale.detail": "La plupart des jeux d'éléments que vous détenez ont dépassé la limite de péremption de 14 jours — {{label}}. Le satellite médian est encore à jour, l'âge affiché paraît donc calme ; pour le reste du catalogue, horaires de passage, pointage et Doppler dérivent. Rafraîchissez depuis la section Satellites ou Réglages ▸ Radio ▸ Éléments orbitaux.",
