  "sat.lane.stale.message": "Sat : éléments de {{days}} j",
  "sat.lane.unusable.detail": "Tous les jeux d'éléments en cache ont plus de 30 jours — les écrans satellite refusent de pointer ou d'accorder dessus. Rafraîchissez dans Réglages ▸ Radio ▸ Éléments orbitaux, ou importez un fichier récent.",
