  "sat.lockOn.label": "Recaler",
  "sat.lockOn.name": "VFO",
  "sat.lockOn.state": "vous avez quitté le transpondeur ? remettez la radio sur le satellite",
  "sat.lockOn.title": "Rejoue votre choix de transpondeur — route, règle la bande et le mode, écrit les deux voies et vous recentre dans la bande passante. À utiliser après avoir déplacé le VFO hors du transpondeur à la main, ou quand la radio est revenue ailleurs.",
  "sat.log.note": "Enregistre le contact depuis votre VFO, exactement comme les panneaux de journal Phone et CW. Sur la liaison descendante d'un satellite que LoTW reconnaît — celui que vous travaillez, ou le dernier travaillé jusqu'à ce que vous en choisissiez un autre — Nexus le marque pour vous : il écrit les champs ADIF PROP_MODE et SAT_NAME, le contact compte donc pour le crédit satellite LoTW <b>et pour vos propres totaux satellite dans Nexus</b>. Tout le reste est enregistré comme un contact ordinaire, et sur 2 m son locator compte pour votre VUCC terrestre, qu'un contact satellite ne rapporte pas. Pour en marquer un vous-même, ajoutez les <b>deux</b> champs — l'un sans l'autre est refusé à la signature.",
  "sat.log.note.title": "Enregistre le contact depuis votre VFO, exactement comme les panneaux de journal Phone et CW. Sur la liaison descendante d'un satellite que LoTW reconnaît — celui que vous travaillez, ou le dernier travaillé jusqu'à ce que vous en choisissiez un autre — Nexus le marque pour vous : il écrit les champs ADIF PROP_MODE et SAT_NAME, le contact compte donc pour le crédit satellite LoTW et pour vos propres totaux satellite dans Nexus. Tout le reste est enregistré comme un contact ordinaire, et sur 2 m son locator compte pour votre VUCC terrestre, qu'un contact satellite ne rapporte pas. Pour en marquer un vous-même, ajoutez les DEUX champs — l'un sans l'autre est refusé à la signature.",
  "sat.noGrid": "Indiquez d'abord votre locator (Réglages ▸ Station) — les passages sont calculés au-dessus de VOTRE position, et sans locator il n'y a rien d'honnête à afficher.",
