  "settings.confirmations.cloudlog.note": "Transmet automatiquement chaque QSO enregistré vers votre journal <b>Cloudlog</b> ou <b>Wavelog</b> auto-hébergé (HTTP). La clé API est un jeton propre à votre instance — saisissez-la, indiquez l'id de votre profil de station et activez l'interrupteur.",
