  "settings.confirmations.qrz.apiKey.label": "Clé API QRZ Logbook",
  "settings.confirmations.qrz.apiKey.placeholder": "depuis la page de réglages de votre logbook QRZ",
  "settings.confirmations.qrz.autoSync.hint": "À mesure que les correspondants confirment sur QRZ, les confirmations arrivent toutes seules — inutile d'appuyer sur Synchroniser. Après la première fois, seuls les CHANGEMENTS sont récupérés. Les confirmations QRZ s'affichent comme confirmées mais ne comptent jamais pour le DXCC ni le WAS, qui exigent LoTW ou une carte.",
  "settings.confirmations.qrz.autoSync.label": "Récupérer les confirmations automatiquement",
  "settings.confirmations.qrz.autoSync.lastPull": "Dernière récupération : {{when}}.",
  "settings.confirmations.qrz.password.hint": "Le mot de passe de connexion QRZ.com — <b>c'est lui qui alimente les recherches dans l'annuaire</b> (nom, QTH, locator), et il est distinct de la clé API Logbook de QRZ, dans Journal et connecteurs (cette clé ne sert qu'à envoyer les QSO). Conservé dans le trousseau du système, jamais sur le disque. Le locator et l'État exigent un abonnement QRZ XML ; les comptes gratuits ne renvoient que nom/adresse/pays.",
  "settings.confirmations.qrz.password.label": "Mot de passe QRZ",
  "settings.confirmations.qrz.password.placeholder": "mot de passe du compte QRZ.com",
  "settings.confirmations.qrz.sync.action": "Synchroniser depuis QRZ",
  "settings.confirmations.qrz.sync.busy": "Synchronisation…",
  "settings.confirmations.qrz.sync.hint": "<b>Récupère</b> votre logbook QRZ — ajoute les QSO enregistrés ailleurs (par ex. une appli mobile sur le terrain) et marque les contacts confirmés sur QRZ. Les confirmations QRZ comptent comme confirmations mais <b>pas</b> pour le DXCC/WAS. Peut être relancé sans risque (dédoublonné). Demande la clé API Logbook ci-dessus.",
  "settings.confirmations.qrz.sync.label": "Synchro bidirectionnelle",
  "settings.confirmations.qrz.sync.title": "RÉCUPÈRE votre logbook QRZ en ligne et le fusionne — ramène les QSO enregistrés ailleurs et leurs confirmations",
  "settings.confirmations.qrz.upload.hint": "Envoie chaque QSO enregistré vers votre logbook QRZ (demande la clé API Logbook ci-dessus).",
  "settings.confirmations.qrz.upload.label": "Envoyer les QSO vers QRZ automatiquement",
  "settings.confirmations.qrz.username.hint": "Sert à retrouver le nom et le locator d'un indicatif au moment de l'enregistrement. Enregistrer les réglages pour appliquer.",
  "settings.confirmations.qrz.username.label": "Identifiant QRZ",
  "settings.confirmations.qrz.username.placeholder": "votre identifiant de compte QRZ.com",
  "settings.confirmations.repeaterbook.token.forget.title": "Retirer le jeton RepeaterBook enregistré du trousseau système",
  "settings.confirmations.repeaterbook.token.hint": "Facultatif. Sans jeton, la section <b>Relais</b> utilise l'annuaire ouvert hearham.com. Ajoutez un jeton personnel (page <b>API Apps</b> de votre compte RepeaterBook) pour interroger RepeaterBook.com sous votre propre compte. Conservé dans le trousseau du système. Un accès RepeaterBook partagé pour tous les utilisateurs de Nexus attend l'accord de RepeaterBook ; si RepeaterBook est injoignable, la section Relais se rabat sur hearham.com.",
  "settings.confirmations.repeaterbook.token.label": "Jeton API RepeaterBook",
