  "settings.contestAids.legend": "Super Check Partial et historique des indicatifs",
  "settings.contestAids.scp.label": "Super Check Partial",
  "settings.contestAids.scp.hint": "Affiche les indicatifs actifs dans les concours récents qui correspondent à ce que tu tapes dans la case Indicatif de la barre de concours. Nexus télécharge la liste (MASTER.SCP, environ 360 Ko d’indicatifs) depuis supercheckpartial.com, tenu par W9KKN, la première fois qu’un concours démarre avec cette option active. Elle n’est jamais livrée avec Nexus.",
  "settings.contestAids.auto.label": "Chercher une liste plus récente une fois par jour",
  "settings.contestAids.auto.hint": "Pendant un concours, Nexus demande au site au plus une fois par jour si la liste a changé, et ne la télécharge que dans ce cas. Désactivé garde ta liste ; Mettre à jour vérifie quand même.",
