  "settings.contestAids.unassisted": "Le mode sans assistance est actif, donc Super Check Partial et l’historique des indicatifs sont désactivés jusqu’à sa fin.",
  "settings.contestAids.history.label": "Historique des indicatifs",
  "settings.contestAids.history.hint": "Un fichier d’historique des indicatifs que tu choisis, au format N1MM. Quand tu tapes un indicatif qui s’y trouve, Nexus remplit les cases de l’échange qu’il peut vérifier (un comté, un État, une section ou une zone que le concours accepte) et les marque ; ce que tu tapes l’emporte toujours. Un fichier ne sert qu’au concours pour lequel il a été importé, et ne quitte jamais cet ordinateur.",
