  "settings.contestKeys.legend": "Entrée envoie le message (ESM)",
  "settings.contestKeys.hint": "Avec ESM activé, Entrée dans la bande de log du concours envoie le message suivant du contact depuis tes touches F, et le contact est enregistré à sa dernière étape. ESM reste désactivé jusqu’à ce que tu l’actives, dans chaque cockpit séparément. Entrée n’active jamais TX, et rien n’est envoyé par minuterie.",
  "settings.contestKeys.cw.label": "ESM dans le cockpit CW",
  "settings.contestKeys.rtty.label": "ESM dans le cockpit RTTY",
  "settings.contestKeys.phone.label": "ESM dans le cockpit Phone",
  "settings.contestKeys.phone.hint": "Entrée joue les enregistrements du voice keyer. Quand tu fais du Run, tu dis toi-même son indicatif et ton échange : un enregistrement ne peut pas dire un indicatif.",
  "settings.contestKeys.callOnce.label": "Indicatif une fois (S&P)",
  "settings.contestKeys.callOnce.hint": "En search and pounce, ton indicatif part une fois par station. L’Entrée suivante demande une répétition au lieu de renvoyer ton indicatif.",
  "settings.contestKeys.cw.steps.label": "Étapes CW : {{profile}}",
  "settings.contestKeys.cw.steps.builtIn": "Ce profil utilise les jeux intégrés, donc en concours ses étapes sont les leurs. Pour associer tes propres touches, personnalise le profil dans Réglages ▸ CW.",
  "settings.contestKeys.cw.steps.own": "Enregistré avec ce profil. Une étape sans touche n’envoie rien, et la bande de log la nomme.",
