  "contest.esm.switch.label": "Enter Sends Message",
  "contest.esm.switch.title": "Enter Sends Message: with it on, Enter in the contest strip sends the contact’s next message from your F-keys, and logs the contact at its last step. Enter never turns TX on. It is off until you turn it on, in each cockpit separately.",
