  "settings.orbitalElements.import.title": "Importer un fichier d'éléments téléchargé (TLE Celestrak, keps AMSAT, jeu SupGP d'un nouveau lancement) — la porte de sortie pour un shack hors ligne. Les imports survivent aux rafraîchissements ; l'époque la plus récente l'emporte pour chaque satellite.",
