  "settings.pounce.threshold.label": "M'alerter pour",
  "settings.pounce.threshold.off": "Désactivé (par défaut)",
  "settings.profiles.delete.action": "Supprimer",
  "settings.profiles.legend": "Profils",
  "settings.profiles.list.hint": "Changer toute une configuration radio / antenne / CAT / bandes d'un seul coup.",
