  "settings.radios.name.placeholder": "Nom de la radio",
  "settings.radios.remove.action": "Retirer",
  "settings.radios.remove.confirm.action": "Retirer la radio",
  "settings.radios.remove.confirm.body": "Sa configuration CAT/audio, son port rigctld et sa couverture de bandes sont supprimés. Votre journal de trafic n'est pas touché. C'est irréversible.",
  "settings.radios.remove.confirm.title": "Retirer {{name}} ?",
  "settings.radios.remove.failed": "Impossible de retirer la radio",
  "settings.radios.remove.title": "Retirer cette radio de la liste",
