  "settings.radios.disable.action": "Désactiver",
  "settings.radios.disable.title": "Ne plus utiliser cette radio pour l'instant : sa configuration est conservée, et Nexus libère son port CAT pour qu'un autre programme puisse utiliser le poste.",
  "settings.radios.disable.title.blocked": "C'est votre radio active — rendez d'abord une autre radio active, puis désactivez celle-ci.",
  "settings.radios.enable.action": "Activer",
