  "settings.workingFrequencies.stock.dial": "VFO (MHz)",
  "settings.workingFrequencies.stock.hint": "Fréquences VFO d'origine WSJT-X. Une ligne avec une surcharge active affiche votre valeur (en surbrillance) au lieu de celle d'origine.",
  "settings.workingFrequencies.stock.label": "Table standard (lecture seule)",
