  "settings.workspace.density.hint": "À quel point les lignes et les contrôles sont serrés. Compact en met plus à l'écran. Tactile agrandit les boutons pour le doigt.",
  "settings.workspace.density.touch": "Tactile",
  "settings.workspace.localClock.label": "Heure locale à côté de l'UTC",
  "settings.workspace.localClock.on": "Oui",
  "settings.workspace.localClock.off": "Non",
  "settings.workspace.localClock.hint": "Affiche l'heure locale de cet ordinateur à côté de l'horloge UTC dans la barre du haut. Le journal, les spots et les périodes FT utilisent toujours l'UTC.",
  "settings.dataFolder.legend": "Dossier des données et du journal",
  "settings.dataFolder.note": "Votre journal, les tables de données téléchargées par Nexus et la boîte Winlink se trouvent dans un même dossier. Gardez-le sur un disque à l'intérieur de cet ordinateur. Nexus tient votre journal dans une base de données, et une base de données sur un lecteur réseau peut être endommagée par le fonctionnement du verrouillage de fichiers à travers le réseau — un lecteur réseau est donc refusé. Un dossier synchronisé (Dropbox, OneDrive, iCloud, Google Drive) est accepté, mais un SEUL Nexus peut l'utiliser à la fois : deux ordinateurs qui écrivent un journal via un service de synchronisation produisent une copie en conflit, pas un journal fusionné.",
  "settings.dataFolder.onNetwork": "Ce dossier est sur un lecteur réseau. Nexus tient votre journal dans une base de données, et une base de données sur un stockage réseau peut être endommagée par le fonctionnement du verrouillage de fichiers à travers le réseau — au pire, le journal ne s'ouvrira plus du tout. Copiez le dossier sur un disque à l'intérieur de cet ordinateur et pointez Nexus vers la copie.",
  "settings.dataFolder.onSync": "Ce dossier semble synchronisé par Dropbox, OneDrive, iCloud ou Google Drive. Un SEUL Nexus peut l'utiliser à la fois — deux ordinateurs qui écrivent un journal via un service de synchronisation produisent une copie en conflit, pas un journal fusionné.",
  "settings.dataFolder.current.label": "Dossier utilisé",
  "settings.dataFolder.source.env": "Défini par NEXUS_DATA_DIR pour ce lancement, ce qui l'emporte sur ce réglage.",
  "settings.dataFolder.source.chosen": "Choisi ici.",
  "settings.dataFolder.source.default": "Le dossier par défaut.",
  "settings.dataFolder.pending": "Choisi : {{path}} — Nexus l'utilisera au prochain démarrage.",
  "settings.dataFolder.path.label": "Nouveau dossier",
  "settings.dataFolder.browse": "Parcourir…",
  "settings.dataFolder.browse.title": "Choisissez le dossier sur votre ordinateur au lieu de taper le chemin. Cela ne fait que remplir le champ : rien ne change tant que vous n'avez pas cliqué sur l'un des boutons ci-dessous.",
  "settings.dataFolder.browse.failed": "Impossible d'ouvrir le sélecteur de dossier",
  "settings.dataFolder.use": "Utiliser ce dossier",
  "settings.dataFolder.use.title": "Utiliser ce dossier dès le prochain démarrage. Rien n'est copié : le dossier doit déjà contenir votre journal.",
  "settings.dataFolder.copy": "Y copier mon journal et mes données",
  "settings.dataFolder.copy.title": "Copie le journal, les tables de données et la boîte Winlink vers le nouveau dossier, vérifie chaque fichier copié par rapport à l'original, puis l'utilise dès le prochain démarrage. Votre ancien dossier reste intact.",
  "settings.dataFolder.reset": "Utiliser le dossier par défaut",
  "settings.dataFolder.reset.title": "Oublier le dossier choisi et revenir au dossier par défaut au prochain démarrage. Rien n'est supprimé.",
  "settings.dataFolder.restart": "Un nouveau dossier est utilisé au prochain démarrage de Nexus. Rien n'est jamais déplacé ni supprimé : votre ancien dossier reste tel quel.",
  "settings.dataFolder.snapshots.label": "Garder les contacts supprimés (jours)",
  "settings.dataFolder.snapshots.hint": "Pendant combien de temps Supprimés récemment et Annuler peuvent rétablir un contact supprimé ou purgé. Ensuite, sa copie est retirée de l'historique du journal au démarrage de Nexus. Les valeurs avant et après de chaque modification sont gardées pour toujours. 0 garde aussi les contacts supprimés pour toujours.",
  "settings.dataFolder.copied": "{{files}} fichiers copiés ({{bytes}} octets) et chacun vérifié par rapport à l'original. Nexus utilisera le nouveau dossier au prochain démarrage.",
  "settings.dataFolder.chosen": "Enregistré. Nexus utilisera le nouveau dossier au prochain démarrage.",
