  "settings.workspace.density.standard": "Standard",
  "settings.workspace.language.hint": "La langue dans laquelle Nexus écrit. Les fréquences, les reports, les indicatifs, les locators, les noms de bande et de mode ne sont jamais traduits ni reformatés — un VFO se lit pareil dans toutes les langues.",
