  "settings.workspace.looks.undo": "Annuler",
  "settings.workspace.looks.undo.title": "Remettre les réglages d’avant ce style",
  "settings.workspace.looks.hint": "Shack, Field / POTA et Nuit préparent tout l’écran. Concours, Grand et net et Tactile règlent la taille du texte, la densité et le contraste, et laissent le mode Field et Nuit tels quels. Aucun style ne change votre thème, l’échelle de l’interface, les couleurs, les palettes de la cascade ni une Nuit réglée sur Auto.",
  "settings.theme.legend": "Thème",
  "settings.waterfallScopes.legend": "Cascade et spectres",
  "settings.waterfallScopes.note": "Les couleurs des cascades et des spectres : les deux mêmes réglages que les sélecteurs des cockpits. Turbo est la valeur par défaut. Cividis paraît presque identique à un œil daltonien rouge-vert et à tout le monde.",
  "settings.waterfallScopes.shared.label": "Phone, CW, RTTY et SSTV",
