  "settings.mapGlobe.legend": "Carte et globe",
  "settings.mapGlobe.note": "La vue de la carte Conditions (Globe, Plate ou Azimutale), ses calques et ses couleurs se choisissent sur la carte elle-même, et Conditions garde un jeu distinct pour chaque activité que vous y choisissez.",
  "settings.performance.legend": "Performances",
