  "settings.performance.motion.reduce": "Réduire",
  "settings.performance.motion.hint": "Réduire coupe les animations et les fondus, ce qui aide aussi un ordinateur lent. Les alertes s’affichent toujours ; elles cessent seulement de clignoter. « Comme l’ordinateur » suit le réglage de réduction des animations de votre système.",
  "settings.workspace.panes.hint": "Rétablir les largeurs par défaut des panneaux gauche et droit.",
  "settings.workspace.panes.label": "Tailles des panneaux",
  "settings.workspace.panes.reset": "Réinitialiser les tailles",
  "settings.workspace.scale.aria": "Échelle de l'interface",
  "settings.workspace.scale.auto": "Auto (ajusté)",
  "settings.workspace.scale.auto.hint.full": "Ajuste toute l'interface à la fenêtre pour que rien ne soit coupé (actuellement {{scale}}%). La cascade reste nette. Augmentez le maximum pour les grands écrans.",
  "settings.workspace.scale.auto.hint.limited": "Ajuste toute l'interface à la fenêtre pour que rien ne soit coupé (actuellement {{scale}}%). Cette fenêtre va jusqu'à {{fits}}% ; au-delà il faut une fenêtre ou un écran plus grand. La cascade reste nette.",
  "settings.workspace.scale.auto.hint.tooSmall": "Ajuste toute l'interface à la fenêtre pour que rien ne soit coupé (actuellement {{scale}}%). Cette fenêtre plafonne à {{fits}}% — augmenter le maximum ne sert à rien tant que la fenêtre n'est pas agrandie ; passez en Manuel pour forcer une échelle plus grande.",
  "settings.workspace.scale.cap.aria": "Échelle maximale de l'interface",
