  "settings.workspace.scale.mode.aria": "Mode d'échelle de l'interface",
  "settings.workspace.textSize.hint": "Agrandit tout le texte, y compris les listes de décodage et le journal. L'échelle de l'interface, au-dessus, agrandit tout l'écran.",
  "settings.workspace.textSize.label": "Taille du texte",
