  "settings.workspace.textSize.normal": "Normale",
  "settings.workspace.theme.hint": "Le thème clair se lit mieux dehors en plein jour ; le bouton Field de la barre du haut augmente le contraste et la taille quel que soit le thème.",
  "settings.workspace.theme.label": "Thème",
  "settings.workspace.contrast.label": "Contraste \u00e9lev\u00e9",
  "settings.workspace.contrast.on": "Activ\u00e9",
  "settings.workspace.contrast.off": "D\u00e9sactiv\u00e9",
  "settings.workspace.contrast.hint": "Plus de contraste entre le texte et le fond, quel que soit le th\u00e8me, \u00e0 la taille que vous avez d\u00e9j\u00e0 choisie. Activez-le si l\u2019\u00e9cran est difficile \u00e0 lire : la mise \u00e0 l\u2019\u00e9chelle de l\u2019interface ne change pas.",
  "settings.workspace.contrast.hint.field": "Le mode Field est activ\u00e9, le contraste \u00e9lev\u00e9 s\u2019applique donc d\u00e9j\u00e0. Ce r\u00e9glage est votre choix permanent et c\u2019est ce que l\u2019\u00e9cran conserve lorsque vous d\u00e9sactivez le mode Field.",
  "settings.workspace.night.label": "Nuit",
  "settings.workspace.night.off": "Désactivé",
  "settings.workspace.night.on": "Activé",
  "settings.workspace.night.auto": "Auto",
  "settings.workspace.night.hint": "Un écran plus sombre et plus chaud pour trafiquer la nuit, quel que soit le thème. Le rouge d’émission, les alertes et les couleurs de signal restent exactement les mêmes.",
  "settings.workspace.night.hint.auto": "S’active au crépuscule et se désactive à l’aube à votre locator : quand le soleil y est à 6° sous l’horizon.",
  "settings.workspace.night.hint.noGrid": "Auto a besoin de votre locator (Réglages ▸ Station ▸ Locator) pour savoir quand le soleil se couche. En attendant, Nuit reste désactivé.",
