  "setup.finish.license.extra": "Amateur Extra",
  "setup.finish.license.extra.blurb": "US — tous les privilèges",
  "setup.finish.license.general": "General",
  "setup.finish.license.general.blurb": "US — la plupart des privilèges HF",
  "setup.finish.license.novice": "Novice",
