  "setup.finish.packs.meta": "{{count}} canaux · {{region}}",
  "setup.finish.packs.sub": "Facultatif — un jeu prêt à l’emploi de fréquences et de réseaux courants, ajouté à vos Mémoires. Modifiez-les ou retirez-les plus tard dans la section Mémoires.",
  "setup.finish.packs.title": "Commencer avec des canaux ?",
  "setup.finish.sub": "Tous les modes et toutes les sections démarrent ACTIVÉS — FT8/FT4, Phone, CW, RTTY, SSTV, APRS, satellites, les cartes, tout. Nexus est un seul programme au lieu de six ; il n’y a rien à déverrouiller. Si vous voulez une application plus légère, retirez des sections dans les Réglages.",
