  "setup.log.result.none": "⚠ Aucun QSO trouvé dans ce fichier — est-ce bien un export ADIF standard (.adi/.adif) ?",
  "setup.log.sources": "Depuis WSJT-X, N1MM, Log4OM, HRD, QRZ, LoTW, ClubLog — tout export ADIF standard (.adi/.adif). Rien ne quitte votre ordinateur ; les doublons sont détectés et ignorés.",
  "setup.log.sub": "Nexus fonctionne au mieux quand il connaît votre historique. Importer votre journal ADIF alimente les indicateurs <b>déjà contacté</b>, le tableau <b>Manquants</b> (nouveaux DXCC / états / locators) et votre progression vers les <b>diplômes</b> — sans lui, l’application démarre aveugle et traite chaque station comme nouvelle. C’est facultatif et vous pouvez importer à tout moment depuis le Journal, mais c’est ce qui rend l’application utile dès le premier jour.",
