  "setup.rig.tci.hint": "Activez d'abord le serveur TCI dans le programme SDR : ExpertSDR3 et Thetis sont réglés d'usine sur le port 50001, piHPSDR sur 40001. Bêta : Nexus pilote la radio et émet par TCI, et l'audio passe aussi par TCI, sans câble audio virtuel.",
