  "setup.rig.detect.action": "🔍 Détecter ma radio",
  "setup.rig.detect.busy": "Détection…",
  "setup.rig.detect.empty": "Rien trouvé — USB : branchez + allumez ; Flex : doit être sur ce réseau ; programme SDR : activez son serveur TCI. Ou passez et configurez plus tard.",
  "setup.rig.detect.failed": "La détection a rencontré une erreur : {{error}}. Vous pouvez toujours choisir votre radio à la main ci-dessous, ou passer et la configurer plus tard.",
