  "setup.rig.flexNote.other": "{{radio}} à {{ip}} — modèle et adresse radio enregistrés. SmartSDR CAT n’existe que sous Windows : indiquez dans Adresse réseau, ci-dessous, l’adresse d’un PC Windows qui l’exécute (slice A = son port 5002), puis testez CAT.",
  "setup.rig.flexNote.windows": "{{radio}} à {{ip}} — CAT réglé via SmartSDR CAT (slice A, port 5002 ; une seconde slice utilise 60001), adresse radio enregistrée pour le panadapter natif/DAX. Testez CAT ci-dessous.",
  "setup.rig.keying.dtr.blurb": "Elle manipule la radio par la ligne DTR du port série.",
  "setup.rig.keying.rts.blurb": "Elle manipule la radio par la ligne RTS du port série, comme un Digirig Mobile.",
  "setup.rig.keying.title": "Comment votre interface manipule-t-elle la radio ?",
  "setup.rig.keying.vox.blurb": "Elle manipule la radio quand elle entend de l'audio, comme un SignaLink.",
  "setup.rig.model.confirm": "Confirmez le modèle exact — les radios à débit fixe voient leur baud réglé automatiquement.",
  "setup.rig.model.label": "Quelle radio est-ce ?",
