  "setup.rig.model.unknownResponder": "inconnu",
  "setup.rig.model.unnamed": "Modèle {{model}}",
  "setup.rig.network.hint": "Une Flex trouvée configure le chemin éprouvé par WSJT-X : CAT via l’application SmartSDR CAT sur ce PC — son port TCP par défaut 5002 pilote la slice A (ports par slice : B=60001, C=60002) — et audio via DAX. Autres radios réseau : choisissez leur modèle plus tard dans Réglages ▸ Radio ▸ Radio et CAT.",
