  "setup.rig.sub": "Une seule détection trouve tout — radios USB, FlexRadio sur le réseau et le serveur TCI d'un programme SDR sur cet ordinateur. Facultatif ; Réglages ▸ Radio ▸ Radio et CAT reprend tout cela plus tard (Tester CAT compris).",
