  "setup.station.callsign.label": "Indicatif",
  "setup.station.grid.hint": "Locator Maidenhead (qrz.com affiche le vôtre). Donnez les 6 — 4 caractères vous placent au milieu d’un carré de ~100 miles de côté, et toutes les distances et tous les azimuts sont mesurés depuis là.",
  "setup.station.grid.invalid": "Ce n’est pas un locator Maidenhead — 4 ou 6 caractères, comme {{short}} ou {{long}}.",
  "setup.station.grid.label": "Locator",
  "setup.station.sub": "Votre locator est la référence de tout ce qui dépend de la position — passages satellite, propagation, carte et fenêtres DXpédition en sont tous calculés.",
