  "setup.steps.station": "Votre station",
  "setup.steps.about": "À propos de vous",
  "setup.about.title": "Quelle est votre expérience ?",
  "setup.about.sub": "Votre réponse détermine les écrans activés au départ, la part des Réglages ouverte d’emblée et ce que propose la dernière étape. Modifiez-la à tout moment dans Réglages ▸ Station. Chaque fonction reste dans les Réglages et leur recherche, quel que soit votre choix.",
  "setup.about.newToHobby": "Nouveau dans le hobby",
  "setup.about.newToHobby.blurb": "Une licence toute neuve, ou bientôt. Nexus démarre avec le FT8, le log et les cartes, et vous guide pour votre premier contact.",
  "setup.about.newToDigital": "Nouveau en modes numériques",
  "setup.about.newToDigital.blurb": "Vous trafiquez en phonie ou en CW et découvrez le FT8 et les autres modes numériques. Les écrans Phone et CW restent activés.",
  "setup.about.experienced": "Expérimenté",
  "setup.about.experienced.blurb": "Tous les écrans activés et tous les Réglages ouverts, comme vous vous y attendez.",
  "setup.finish.walk.label": "Me guider pour mon premier contact FT8",
  "setup.finish.walk.blurb": "Quatre lignes courtes après Terminer. Rien n’est modifié ni émis.",
  "firstContact.title": "Votre premier contact FT8",
  "firstContact.sub": "Lire ceci ne modifie aucun réglage et n’émet rien.",
  "firstContact.step.listen": "Écoutez d’abord. Avec la radio connectée et sur une fréquence FT8, les stations que Nexus entend apparaissent dans Activité bande toutes les 15 secondes.",
  "firstContact.step.cq": "Une ligne avec CQ est une station qui appelle tout le monde. Plus le nombre en dB est élevé, plus le signal est fort.",
  "firstContact.step.answer": "Double-cliquez sur cette ligne pour répondre. Cela active TX : Nexus appelle la station tout de suite ou à la période suivante et envoie pour vous chaque message du contact.",
  "firstContact.step.answer.manual": "Double-cliquez sur cette ligne pour répondre. TX reste désactivé, car {{setting}} est désactivé dans les Réglages : appuyez sur {{txOff}} pour activer TX, puis Nexus appelle la station et envoie pour vous chaque message du contact.",
  "firstContact.step.tx": "TX est désactivé à chaque ouverture de Nexus ({{txOff}}). {{stop}} arrête une émission immédiatement ; {{txOn}} désactive TX à la fin de la période en cours.",
  "firstContact.close": "Compris",
  "settings.station.experience.label": "Votre expérience",
  "settings.station.experience.notSet": "Non défini",
  "settings.station.experience.hint": "Détermine les écrans activés et la part des Réglages ouverte d’emblée. Le changer remplace l’ensemble défini dans Réglages ▸ Apparence ▸ Fonctions. Chaque réglage reste accessible par la recherche.",
  "settings.station.experience.failed": "Impossible d’enregistrer votre expérience",
