  "topbar.clock.corrected.title": "L'horloge du PC est à {{offset}} de l'UTC et Nexus le corrige déjà — les fenêtres d'émission et de décodage tombent sur la vraie grille UTC. Mesuré il y a {{age}}, {{servers}} serveurs de temps concordants.",
